569	/// Get the possible values for completion
570	fn possible_values(
571	    a: &clap::Arg,
572	) -> Option<Box<dyn Iterator<Item = clap::builder::PossibleValue> + '_>> {
573	    if !a.get_num_args().expect("built").takes_values() {
574	        None
575	    } else {
576	        a.get_value_parser().possible_values()
577	    }
578	}
