1	use std::any::type_name;
2	use std::ffi::OsStr;
3	use std::ffi::OsString;
4	use std::sync::Arc;
5	
6	use clap::builder::ArgExt;
7	use clap::builder::CommandExt;
8	use clap_lex::OsStrExt as _;
9	
10	use super::CompletionCandidate;
11	
12	/// Extend [`Arg`][clap::Arg] with a completer
13	///
14	/// # Example
15	///
16	/// ```rust
17	/// use clap::Parser;
18	/// use clap_complete::engine::{ArgValueCompleter, CompletionCandidate};
19	///
20	/// fn custom_completer(current: &std::ffi::OsStr) -> Vec<CompletionCandidate> {
21	///     let mut completions = vec![];
22	///     let Some(current) = current.to_str() else {
23	///         return completions;
24	///     };
25	///
26	///     if "foo".starts_with(current) {
27	///         completions.push(CompletionCandidate::new("foo"));
28	///     }
29	///     if "bar".starts_with(current) {
30	///         completions.push(CompletionCandidate::new("bar"));
31	///     }
32	///     if "baz".starts_with(current) {
33	///         completions.push(CompletionCandidate::new("baz"));
34	///     }
35	///     completions
36	/// }
37	///
38	/// #[derive(Debug, Parser)]
39	/// struct Cli {
40	///     #[arg(long, add = ArgValueCompleter::new(custom_completer))]
41	///     custom: Option<String>,
42	/// }
43	/// ```
44	#[derive(Clone)]
45	pub struct ArgValueCompleter(Arc<dyn ValueCompleter>);
46	
47	impl ArgValueCompleter {
48	    /// Create a new `ArgValueCompleter` with a custom completer
49	    pub fn new<C>(completer: C) -> Self
50	    where
51	        C: ValueCompleter + 'static,
52	    {
53	        Self(Arc::new(completer))
54	    }
55	
56	    /// Candidates that match `current`
57	    ///
58	    /// See [`CompletionCandidate`] for more information.
59	    pub fn complete(&self, current: &OsStr) -> Vec<CompletionCandidate> {
60	        self.0.complete(current)
61	    }
62	
63	    /// Candidates that match `current` at `arg_index` within the current occurrence.
64	    ///
65	    /// `arg_index` is the position of the value being completed within an
66	    /// argument's [`num_args`][clap::Arg::num_args] range, starting at `0`.
67	    /// This lets a completer return different candidates for each value of a
68	    /// multi-value argument (for example, a remote name first and a branch
69	    /// name second for `--set-upstream <REMOTE> <BRANCH>`).
70	    ///
71	    /// `arg_index` is unaffected by [`value_delimiter`][clap::Arg::value_delimiter]:
72	    /// it counts shell arguments, not delimiter-separated values.
73	    ///
74	    /// See [`CompletionCandidate`] for more information.
75	    pub fn complete_at(&self, arg_index: usize, current: &OsStr) -> Vec<CompletionCandidate> {
76	        self.0.complete_at(arg_index, current)
77	    }
78	}
79	
80	impl std::fmt::Debug for ArgValueCompleter {
81	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
82	        f.write_str(type_name::<Self>())
83	    }
84	}
85	
86	impl ArgExt for ArgValueCompleter {}
87	
88	/// User-provided completion candidates for an [`Arg`][clap::Arg], see [`ArgValueCompleter`]
89	///
90	/// This is useful when predefined value hints are not enough.
91	pub trait ValueCompleter: Send + Sync {
92	    /// All potential candidates for an argument.
93	    ///
94	    /// See [`CompletionCandidate`] for more information.
95	    fn complete(&self, current: &OsStr) -> Vec<CompletionCandidate>;
96	
97	    /// All potential candidates for the value at `arg_index` within the current occurrence.
98	    ///
99	    /// `arg_index` is the position of the value being completed within an
100	    /// argument's [`num_args`][clap::Arg::num_args] range, starting at `0`.
101	    /// This lets a completer return different candidates for each value of a
102	    /// multi-value argument (for example, a remote name first and a branch
103	    /// name second for `--set-upstream <REMOTE> <BRANCH>`).
104	    ///
105	    /// `arg_index` is unaffected by [`value_delimiter`][clap::Arg::value_delimiter]:
106	    /// it counts shell arguments, not delimiter-separated values.
107	    ///
108	    /// See [`CompletionCandidate`] for more information.
109	    fn complete_at(&self, arg_index: usize, current: &OsStr) -> Vec<CompletionCandidate> {
110	        let _ = arg_index;
111	        self.complete(current)
112	    }
113	}
114	
115	impl<F> ValueCompleter for F
116	where
117	    F: Fn(&OsStr) -> Vec<CompletionCandidate> + Send + Sync,
118	{
119	    fn complete(&self, current: &OsStr) -> Vec<CompletionCandidate> {
120	        self(current)
121	    }
122	}
123	
124	/// Extend [`Arg`][clap::Arg] with a [`ValueCandidates`]
125	///
126	/// # Example
127	///
128	/// ```rust
129	/// use clap::Parser;
130	/// use clap_complete::engine::{ArgValueCandidates, CompletionCandidate};
131	///
132	/// #[derive(Debug, Parser)]
133	/// struct Cli {
134	///     #[arg(long, add = ArgValueCandidates::new(|| { vec![
135	///         CompletionCandidate::new("foo"),
136	///         CompletionCandidate::new("bar"),
137	///         CompletionCandidate::new("baz")] }))]
138	///     custom: Option<String>,
139	/// }
140	/// ```
141	#[derive(Clone)]
142	pub struct ArgValueCandidates(Arc<dyn ValueCandidates>);
143	
144	impl ArgValueCandidates {
145	    /// Create a new `ArgValueCandidates` with a custom completer
146	    pub fn new<C>(completer: C) -> Self
147	    where
148	        C: ValueCandidates + 'static,
149	    {
150	        Self(Arc::new(completer))
151	    }
152	
153	    /// All potential candidates for an argument.
154	    ///
