337	    let current = current.to_string_lossy();
338	    let search_root = if prefix.is_absolute() {
339	        prefix.to_owned()
340	    } else if prefix.iter().next() == Some(OsStr::new("~")) {
341	        let prefix = prefix.strip_prefix("~").unwrap_or(prefix);
342	        let home_dir = match std::env::home_dir() {
343	            Some(home_dir) => home_dir,
344	            None => {
345	                // Can't complete without a `home_dir`
346	                return completions;
347	            }
348	        };
349	        home_dir.join(prefix)
350	    } else {
