        if let Some(possible_values) = possible_values(arg) {
            let possible_values = possible_values
                .map(|value| value.get_name().to_owned())
                .collect::<Vec<_>>();
            if committed_segments
                .iter()
                .any(|segment| !possible_values.iter().any(|value| value == segment))
